#include <openssl/sha.h>
#include <openssl/bio.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>

char* hash_certificate(const char *cert) {
    // Create a SHA256 context
    SHA256_CTX sha256;
    if (SHA256_Init(&sha256) != 1) {
        return NULL; // Handle initialization error
    }

    // Update the context with the certificate data
    SHA256_Update(&sha256, cert, strlen(cert));

    // Finalize the hash and get the digest bytes
    unsigned char hash[SHA256_DIGEST_LENGTH];
    if (SHA256_Final(hash, &sha256) != 1) {
        return NULL; // Handle finalization error
    }

    // Convert the hash bytes to a hexadecimal string
    char* hex_hash = malloc(2 * SHA256_DIGEST_LENGTH + 1);
    if (!hex_hash) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        sprintf(hex_hash + 2*i, "%02x", hash[i]);
    }

    hex_hash[2 * SHA256_DIGEST_LENGTH] = '\0';

    return hex_hash;
}
