#include <openssl/aes.h>
#include <openssl/err.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned char* encrypted_data;
    size_t encrypted_len;
    unsigned char* iv;
    unsigned char* key;
} encryption_result;

encryption_result encrypt_data(
    const unsigned char* key, size_t key_len,
    const unsigned char* data, size_t data_len
) {
    // Determine the appropriate key length for AES (128, 192, or 256 bits)
    int key_bits = (key_len >= 32) ? 256 : (key_len >= 24) ? 192 : 128;
    if(key_bits != 128 && key_bits != 192 && key_bits != 256) {
        // Handle invalid key length
        return (encryption_result){NULL, 0, NULL, NULL};
    }

    AES_KEY aes_key;
    if(AES_set_encrypt_key(key, key_bits, &aes_key) != 0) {
        // Handle key setup failure
        return (encryption_result){NULL, 0, NULL, NULL};
    }

    size_t encrypted_len = data_len;
    unsigned char* encrypted_data = malloc(encrypted_len);
    if(!encrypted_data) {
        // Handle memory allocation failure
        return (encryption_result){NULL, 0, NULL, NULL};
    }

    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);

    AES_cbc_encrypt(data, encrypted_data, data_len, &aes_key, iv, AES_ENCRYPT);

    // Copy the key for the result
    unsigned char* key_copy = malloc(key_len);
    if(!key_copy) {
        free(encrypted_data);
        return (encryption_result){NULL, 0, NULL, NULL};
    }
    memcpy(key_copy, key, key_len);

    encryption_result result = {
        encrypted_data,
        encrypted_len,
        iv,
        key_copy
    };

    return result;
}
