#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* write_results(const char* results) {
    // Generate a temporary file name
    char* temp_file = tmpnam(NULL);

    if (temp_file == NULL) {
        return NULL;  // Handle error: could not create temp file name
    }

    // Open the temporary file for writing
    FILE* file = fopen(temp_file, "w");

    if (file == NULL) {
        free(temp_file);  // Clean up on failure
        return NULL;     // Handle error: could not open temp file
    }

    // Write results to the file
    fprintf(file, "%s", results);

    // Close the file
    fclose(file);

    // Return the temporary file name (note: needs to be freed by caller when done)
    return temp_file;
}
